# Enumerations

# AnnotationStyle
NONE <- 0
WARNING <- 1
ERROR <- 2
ACCENT <- 3

# BackgroundPatternType
NONE <- 0
GRID <- 1

# BracketMatchType
NONE <- 0
OUT_OF_RANGE <- 1
NOT_FOUND <- 2
FOUND <- 3

# ChangeCaseType
LOWER <- 0
UPPER <- 1
TOGGLE <- 2
TITLE <- 3

# CompletionActivation
NONE <- 0
INTERACTIVE <- 1
USER_REQUESTED <- 2

# CompletionColumn
ICON <- 0
BEFORE <- 1
TYPED_TEXT <- 2
AFTER <- 3
COMMENT <- 4
DETAILS <- 5

# CompressionType
NONE <- 0
GZIP <- 1

# FileLoaderError
TOO_BIG <- 0
ENCODING_AUTO_DETECTION_FAILED <- 1
CONVERSION_FALLBACK <- 2

# FileSaverError
INVALID_CHARS <- 0
EXTERNALLY_MODIFIED <- 1

# FileSaverFlags
NONE <- 0
IGNORE_INVALID_CHARS <- 1
IGNORE_MODIFICATION_TIME <- 2
CREATE_BACKUP <- 4

# GutterRendererAlignmentMode
CELL <- 0
FIRST <- 1
LAST <- 2

# NewlineType
LF <- 0
CR <- 1
CR_LF <- 2

# SmartHomeEndType
DISABLED <- 0
BEFORE <- 1
AFTER <- 2
ALWAYS <- 3

# SortFlags
NONE <- 0
CASE_SENSITIVE <- 1
REVERSE_ORDER <- 2
REMOVE_DUPLICATES <- 4
FILENAME <- 8

# SpaceLocationFlags
NONE <- 0
LEADING <- 1
INSIDE_TEXT <- 2
TRAILING <- 4
ALL <- 7

# SpaceTypeFlags
NONE <- 0
SPACE <- 1
TAB <- 2
NEWLINE <- 4
NBSP <- 8
ALL <- 15

# ViewGutterPosition
LINES <- -30
MARKS <- -20
